package com.musiccatalog.controller; import com.musiccatalog.dto.AnalyticsDtos.*; import com.musiccatalog.service.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api") public class AnalyticsController {private final AnalyticsService analytics;private final AiInsightsService ai;public AnalyticsController(AnalyticsService a,AiInsightsService i){analytics=a;ai=i;}@GetMapping("/analytics") public Analytics stats(Authentication a){return analytics.analytics(a.getName());}@PostMapping("/ai/insights") public Insight insights(Authentication a){return ai.generate(a.getName());} }
